//! UI translations. The English text in the code is the lookup key, so a string
//! without a translation simply shows in English.
//!
//! Each language is one file in `data/locales/<code>.toml`, bundled into the
//! binary at build time. Adding a language means adding a file; no code changes.

use std::collections::HashMap;
use std::sync::LazyLock;
use std::sync::atomic::{AtomicUsize, Ordering};

use serde::Deserialize;

use crate::config::language::Language;

// Generated by build.rs: `const BUNDLED_LOCALES: &[(&str, &str)]` of (code, file).
include!(concat!(env!("OUT_DIR"), "/bundled_locales.rs"));

pub struct Locale {
    pub code: String,
    pub name: String,
    strings: HashMap<String, String>,
}

#[derive(Deserialize)]
struct LocaleFile {
    name: String,
    #[serde(default)]
    strings: HashMap<String, String>,
}

static LOCALES: LazyLock<Vec<Locale>> = LazyLock::new(|| {
    let english = Locale {
        code: "en".to_string(),
        name: "English".to_string(),
        strings: HashMap::new(),
    };
    std::iter::once(english)
        .chain(BUNDLED_LOCALES.iter().filter_map(|(code, source)| {
            parse_locale(code, source)
                .map_err(|error| log::error!("Locale {code} is invalid: {error}"))
                .ok()
        }))
        .collect()
});

fn parse_locale(code: &str, source: &str) -> Result<Locale, toml::de::Error> {
    let file: LocaleFile = toml::from_str(source)?;
    Ok(Locale {
        code: code.to_string(),
        name: file.name,
        strings: file.strings,
    })
}

pub fn locales() -> &'static [Locale] {
    &LOCALES
}

static CURRENT: AtomicUsize = AtomicUsize::new(0);

pub fn set_language(language: Language) {
    CURRENT.store(language.0, Ordering::Relaxed);
}

pub fn language() -> Language {
    Language(CURRENT.load(Ordering::Relaxed))
}

/// The text of `english` in the current language.
pub fn tr(english: &str) -> &str {
    locales()
        .get(language().0)
        .and_then(|locale| locale.strings.get(english))
        .map_or(english, String::as_str)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_bundled_locale_parses() {
        for (code, source) in BUNDLED_LOCALES {
            if let Err(error) = parse_locale(code, source) {
                panic!("locales/{code}.toml: {error}");
            }
        }
        assert_eq!(locales().len(), BUNDLED_LOCALES.len() + 1);
    }

    #[test]
    fn translates_and_falls_back_to_english() {
        // The language is global and tests run in parallel, so leave it untouched.
        let zh = Language::from_code("zh-CN").expect("zh-CN is bundled");
        let strings = &locales()[zh.0].strings;
        assert_eq!(strings.get("Theme").map(String::as_str), Some("主题"));
        assert_eq!(
            strings
                .get("Restart required.\nChanges will take effect after restart.")
                .map(String::as_str),
            Some("需要重启。\n重启后生效。")
        );
        assert_eq!(tr("Theme"), "Theme");
        assert_eq!(Language::from_code("SimplifiedChinese"), Some(zh));
    }
}
